  '2026-05-27': 1, '2026-05-28': 1, '2026-05-31': 1, '2026-06-01': 1, '2026-06-16': 1,
  '2026-08-17': 1, '2026-08-25': 1, '2026-12-24': 1, '2026-12-25': 1,
