    juli: '07', agustus: '08', september: '09', oktober: '10', november: '11', nopember: '11', desember: '12'
  };
  const mIndo = s.toLowerCase().match(/(\d{1,2})\s+(januari|februari|maret|april|mei|juni|juli|agustus|september|oktober|november|nopember|desember)\s+(\d{4})/);
  if (mIndo) {
    const dd = String(parseInt(mIndo[1], 10)).padStart(2, '0');
    const mm = months[mIndo[2]] || '';
    if (mm) return mIndo[3] + '-' + mm + '-' + dd;
  }
  return '';
}

function addWorkdaysSkb(baseIso, workdays) {
  const cleanBase = parseIsoDateLocal(baseIso) || new Date().toISOString().slice(0, 10);
  const parts = cleanBase.split('-');
  const dt = new Date(Date.UTC(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10)));
  const steps = parseInt(workdays, 10) || 0;
  if (steps <= 0) return cleanBase;
  let added = 0;
  let guard = 0;
  while (added < steps && guard < 180) {
    dt.setUTCDate(dt.getUTCDate() + 1);
    guard++;
    const dow = dt.getUTCDay();
    const iso = dt.getUTCFullYear() + '-' + String(dt.getUTCMonth() + 1).padStart(2, '0') + '-' + String(dt.getUTCDate()).padStart(2, '0');
    if (dow !== 0 && dow !== 6 && !SKB_HOLIDAYS[iso]) {
      added++;
    }
  }
  return dt.getUTCFullYear() + '-' + String(dt.getUTCMonth() + 1).padStart(2, '0') + '-' + String(dt.getUTCDate()).padStart(2, '0');
}

function resolveAiDateField(explicitVal, catVal, baseIso) {
  const exp = String(explicitVal == null ? '' : explicitVal).trim();
  const cat = String(catVal == null ? '' : catVal).trim().toUpperCase();
  if (/^\d{4}-\d{2}-\d{2}$/.test(exp)) return exp;
  if (cat === 'EKSPLISIT') {
    const parsedExp = parseIsoDateLocal(exp);
    if (parsedExp) return parsedExp;
    if (exp) return exp;
    return addWorkdaysSkb(baseIso, 5);
  }
  if (cat === 'HARI_RAPAT') return parseIsoDateLocal(baseIso) || addWorkdaysSkb('', 0);
  if (cat === 'JANGKA_PENDEK') return addWorkdaysSkb(baseIso, 5);
  if (cat === 'JANGKA_MENENGAH') return addWorkdaysSkb(baseIso, 10);
  if (cat === 'PROYEK_SARANA') return addWorkdaysSkb(baseIso, 15);
  return exp;
}

function toList(val) {
  if (Array.isArray(val)) {
    return val.map((x) => String(x == null ? '' : x).trim()).filter(Boolean);
  }
  const s = String(val == null ? '' : val).trim();
  if (!s) return [];
  return s
    .split(/\r?\n/)
    .map((line) => line.replace(/^\s*[-*•\d.)]+\s*/, '').trim())
    .filter(Boolean);
}

function toNumberedText(list) {
  if (!Array.isArray(list) || list.length === 0) return '';
  if (list.length === 1) return list[0];
  return list.map((line, i) => i + 1 + '. ' + line).join(NL);
}

function dedupeParagraphText(raw) {
  const clean = String(raw == null ? '' : raw).trim();
  if (!clean) return '';
  const parts = clean
    .split(/\r?\n+|(?<=[.!?])\s+/)
    .map((s) => String(s || '').trim())
    .filter(Boolean);
  if (parts.length <= 1) return clean;
  const seen = new Set();
  const out = [];
  for (const part of parts) {
    const norm = part.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    if (!norm || !seen.has(norm)) {
      if (norm) seen.add(norm);
      out.push(part);
    }
  }
  return out.join(' ');
}

function groupPembahasanBySpeaker(rawRows) {
  const order = [];
  const map = Object.create(null);

  for (let i = 0; i < (Array.isArray(rawRows) ? rawRows.length : 0); i++) {
    const row = rawRows[i];
    if (!row || typeof row !== 'object') continue;
    const spkName = String(row.pembicara_nama || 'Pembicara #' + (i + 1)).trim();
    const spkNip = String(row.pembicara_nip || '').trim();
    const spkJab = String(row.pembicara_jabatan || '').trim();
    const isAnon = /^pembicara\s*#?\d+/i.test(spkName) || /belum\s+teridentifikasi/i.test(spkName);
    const baseName = isAnon ? spkName : (spkName.replace(/\([^)]*\)/g, ' ').trim() || spkName);
    const key = spkNip
      ? 'nip:' + spkNip
      : 'name:' + (baseName.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() || 'idx_' + i);

    const rowItems = Array.isArray(row.items) && row.items.length > 0
      ? row.items
      : [{
          uraian: toNumberedText(toList(row.uraian_text || row.uraian)),
          tindak_lanjut: toNumberedText(toList(row.tindak_lanjut_text || row.tindak_lanjut)),
          target: String(row.target || '').trim(),
          penanggung_jawab: String(row.penanggung_jawab || '').trim(),
          tanggal_penyelesaian: String(row.tanggal_penyelesaian || '').trim(),
        }];

    if (!map[key]) {
      map[key] = {
        pembicara_nama: spkName,
        pembicara_nip: spkNip,
        pembicara_jabatan: spkJab,
        items: [],
        seen: Object.create(null),
      };
      order.push(key);
    } else {
      if (!map[key].pembicara_jabatan && spkJab) map[key].pembicara_jabatan = spkJab;
      if (spkName.length > map[key].pembicara_nama.length && spkName.includes('(')) {
        map[key].pembicara_nama = spkName;
      }
    }

    const grp = map[key];
    for (const sub of rowItems) {
      if (!sub || typeof sub !== 'object') continue;
      if (grp.items.length >= 25) break;
      const uStr = String(sub.uraian || '').trim();
      const tStr = String(sub.tindak_lanjut || '').trim();
      const normU = uStr.toLowerCase().replace(/^[0-9]+[.)]\s*/, '').replace(/\s+/g, ' ').trim();
      const normT = tStr.toLowerCase().replace(/^[0-9]+[.)]\s*/, '').replace(/\s+/g, ' ').trim();
      const dKey = normU ? 'u:' + normU : (normT ? 't:' + normT : '');
      if (dKey && grp.seen[dKey] !== undefined) {
        const prev = grp.items[grp.seen[dKey]];
        if (prev && !prev.tindak_lanjut && tStr) prev.tindak_lanjut = tStr;
        if (prev && !prev.penanggung_jawab && sub.penanggung_jawab) prev.penanggung_jawab = String(sub.penanggung_jawab || '').trim();
        continue;
      }
      if (dKey) grp.seen[dKey] = grp.items.length;
      grp.items.push({
        uraian: uStr,
        tindak_lanjut: tStr,
        target: String(sub.target || '').trim(),
        penanggung_jawab: String(sub.penanggung_jawab || '').trim(),
        tanggal_penyelesaian: String(sub.tanggal_penyelesaian || '').trim(),
      });
    }
  }

  return order.slice(0, 30).map((key) => {
    const grp = map[key];
    const flatUraian = grp.items.map((x) => x.uraian).filter(Boolean);
    const flatTindak = grp.items.map((x) => x.tindak_lanjut).filter(Boolean);
    const flatTarget = grp.items.map((x) => x.target).filter(Boolean).join(NL);
    const flatPj = grp.items.map((x) => x.penanggung_jawab).filter(Boolean);
    const flatSelesai = grp.items.map((x) => x.tanggal_penyelesaian).filter(Boolean).join(NL);
    return {
      pembicara_nama: grp.pembicara_nama,
      pembicara_nip: grp.pembicara_nip,
      pembicara_jabatan: grp.pembicara_jabatan,
      uraian: flatUraian,
      uraian_text: toNumberedText(flatUraian),
      tindak_lanjut: flatTindak,
      tindak_lanjut_text: toNumberedText(flatTindak),
      target: flatTarget,
      penanggung_jawab: flatPj.join('; '),
      tanggal_penyelesaian: flatSelesai,
      items: grp.items,
    };
  });
}

function normalizeRowsWithSkb(rawRows, baseIso) {
  return (Array.isArray(rawRows) ? rawRows : []).slice(0, 60).map((r, idx) => {
    const row = r && typeof r === 'object' ? r : {};
    const speakerName = String(row.pembicara_nama || row.pembicara || 'Pembicara #' + (idx + 1)).trim();
    const speakerNip = (/^pembicara\s*#\d+/i.test(speakerName) || /belum\s+teridentifikasi/i.test(speakerName))
      ? ''
      : String(row.pembicara_nip || '').trim();
    const speakerJab = String(row.pembicara_jabatan || '').trim();

    if (Array.isArray(row.items) && row.items.length > 0) {
      const normItems = row.items.slice(0, 25).map((sub) => {
        const it = sub && typeof sub === 'object' ? sub : {};
        const uList = toList(it.uraian_text || it.uraian);
        const tList = toList(it.tindak_lanjut_text || it.tindak_lanjut);
        return {
          uraian: toNumberedText(uList),
          tindak_lanjut: toNumberedText(tList),
          target: resolveAiDateField(it.target_tanggal_eksplisit || it.target, it.target_kategori_waktu, baseIso),
          penanggung_jawab: String(it.penanggung_jawab || row.penanggung_jawab || '').trim(),
          tanggal_penyelesaian: resolveAiDateField(it.selesai_tanggal_eksplisit || it.tanggal_penyelesaian, it.selesai_kategori_waktu, baseIso)
        };
      });
      const flatUraian = normItems.map((x) => x.uraian).filter(Boolean);
      const flatTindak = normItems.map((x) => x.tindak_lanjut).filter(Boolean);
      const flatTarget = normItems.map((x) => x.target).filter(Boolean).join(NL);
      const flatPj = normItems.map((x) => x.penanggung_jawab).filter(Boolean);
      const flatSelesai = normItems.map((x) => x.tanggal_penyelesaian).filter(Boolean).join(NL);
      return {
        pembicara_nama: speakerName,
        pembicara_nip: speakerNip,
        pembicara_jabatan: speakerJab,
        uraian: flatUraian,
        uraian_text: toNumberedText(flatUraian),
        tindak_lanjut: flatTindak,
        tindak_lanjut_text: toNumberedText(flatTindak),
        target: flatTarget,
        penanggung_jawab: flatPj.join('; '),
        tanggal_penyelesaian: flatSelesai,
        items: normItems
      };
    }

    const uraianList = toList(row.uraian_text || row.uraian);
    const tindakList = toList(row.tindak_lanjut_text || row.tindak_lanjut);
    return {
      pembicara_nama: speakerName,
      pembicara_nip: speakerNip,
      pembicara_jabatan: speakerJab,
      uraian: uraianList,
      uraian_text: toNumberedText(uraianList),
      tindak_lanjut: tindakList,
      tindak_lanjut_text: toNumberedText(tindakList),
      target: resolveAiDateField(row.target_tanggal_eksplisit || row.target, row.target_kategori_waktu, baseIso),
      penanggung_jawab: String(row.penanggung_jawab || '').trim(),
      tanggal_penyelesaian: resolveAiDateField(row.selesai_tanggal_eksplisit || row.tanggal_penyelesaian, row.selesai_kategori_waktu, baseIso)
    };
  });
}

