        pembicara_jabatan: String(spk.jabatan || '').trim(),
        items: Array.isArray(spk.segmen) ? spk.segmen.map((seg) => ({
          uraian: String(seg.uraian || '').trim(),
          tindak_lanjut: String(seg.tindak_lanjut || '').trim(),
          target_kategori_waktu: 'JANGKA_PENDEK',
          target_tanggal_eksplisit: '',
          penanggung_jawab: String(seg.penanggung_jawab || '').trim(),
          selesai_kategori_waktu: 'JANGKA_PENDEK',
          selesai_tanggal_eksplisit: '',
        })) : [],
      })),
    };
  }
  return null;
}

const metaItems = $('Siapkan Payload Klip Round-Robin (Code)').all() || [];
const respItems = $input.all() || [];

const allClips = [];
const failedClips = [];

for (let i = 0; i < metaItems.length; i++) {
  const m = (metaItems[i] && metaItems[i].json) ? metaItems[i].json : {};
  if (!m.chunksAvailable) continue;
  const r = (respItems[i] && respItems[i].json) ? respItems[i].json : {};

  let ok = false;
  let rawText = '';
  let parsed = null;
  let errorMsg = '';

  if (r.error) {
    errorMsg = String(r.error.message || r.error || 'Error Gemini Pass 1');
  } else {
    const ex = extractGeminiJson(r);
    rawText = String(ex.rawText || '').trim();
    parsed = normalizeParsedNotulaShape(ex.parsed);
    if (parsed) {
      ok = true;
    } else if (rawText.length >= 20) {
      ok = true;
    } else {
      errorMsg = 'Output segmen kosong/tidak valid.';
    }
  }

  const clipRecord = {
    chunkIndex: Number(m.chunkIndex || 0),
    totalChunks: Number(m.totalChunks || metaItems.length || 1),
    fileName: String(m.fileName || ''),
    timeWindowLabel: String(m.timeWindowLabel || ''),
    modelUsed: String(m.primaryModelName || 'models/gemini-3.5-flash-lite'),
    failoverModelName: String(m.failoverModelName || 'models/gemini-3.8-flash'),
    failoverModelUrl: String(m.failoverModelUrl || ''),
    ok,
    rawText,
    parsed,
    errorMsg,
  };
  allClips.push(clipRecord);

  if (!ok) {
    failedClips.push({
      chunkIndex: clipRecord.chunkIndex,
      totalChunks: clipRecord.totalChunks,
      fileName: clipRecord.fileName,
      timeWindowLabel: clipRecord.timeWindowLabel,
      primaryModelName: clipRecord.modelUsed,
      failoverModelName: clipRecord.failoverModelName,
      failoverModelUrl: clipRecord.failoverModelUrl,
      primaryError: errorMsg,
      chunkGeminiRequestBody: m.chunkGeminiRequestBody,
    });
  }
}

return [
  {
    json: {
      totalChunks: allClips.length,
      allClips,
      failedClips,
      hasFailedClips: failedClips.length > 0,
    },
  },
];

const evalSummary = $input.first().json || {};
const failed = Array.isArray(evalSummary.failedClips) ? evalSummary.failedClips : [];
return failed.map((item) => ({ json: item }));

