const evalSummary = $('Evaluasi Hasil Klip & Cek Failover (Code)').first().json || {};
const baseClips = Array.isArray(evalSummary.allClips)
  ? evalSummary.allClips.map((c) => ({ ...c }))
  : [];

if (evalSummary.hasFailedClips) {
  let failoverMetaItems = [];
  try {
    failoverMetaItems = $('Pecah Klip Gagal Untuk Failover (Code)').all() || [];
  } catch (eFm) {}
  const failoverRespItems = $input.all() || [];

  for (let k = 0; k < failoverMetaItems.length; k++) {
    const fm = (failoverMetaItems[k] && failoverMetaItems[k].json) ? failoverMetaItems[k].json : {};
    const fr = (failoverRespItems[k] && failoverRespItems[k].json) ? failoverRespItems[k].json : {};
    const slot = baseClips.find((c) => Number(c.chunkIndex) === Number(fm.chunkIndex));
    if (!slot) continue;

    if (fr.error) {
      slot.errorMsg = (slot.errorMsg ? slot.errorMsg + ' | ' : '') + 'Failover (' + (fm.failoverModelName || 'cadangan') + '): ' + String(fr.error.message || fr.error);
    } else {
      const exF = extractGeminiJson(fr);
      const rawF = String(exF.rawText || '').trim();
      const parsedF = normalizeParsedNotulaShape(exF.parsed);
      if (parsedF || rawF.length >= 20) {
        slot.ok = true;
        slot.modelUsed = String(fm.failoverModelName || slot.failoverModelName);
        slot.rawText = rawF;
        slot.parsed = parsedF;
        slot.errorMsg = '';
      } else {
        slot.errorMsg = (slot.errorMsg ? slot.errorMsg + ' | ' : '') + 'Failover kosong/tidak valid.';
      }
    }
  }
}

baseClips.sort((a, b) => Number(a.chunkIndex) - Number(b.chunkIndex));

const textSections = [];
const failedErrors = [];
let dasarOpsional = '';
const pengarahanParts = [];
const kesimpulanParts = [];
const transkripParts = [];
const mergedPembahasan = [];
let okCount = 0;

for (const c of baseClips) {
  if (c.ok && c.rawText) {
    okCount++;
    textSections.push(
      '=== SEGMEN ' + (Number(c.chunkIndex) + 1) + '/' + Number(c.totalChunks || baseClips.length) +
      ' (' + String(c.timeWindowLabel || '-') + ' | Model: ' + String(c.modelUsed || '-') + ') ===' +
      NL + c.rawText
    );
    if (c.parsed && typeof c.parsed === 'object') {
      if (!dasarOpsional && String(c.parsed.dasar_opsional || '').trim()) {
        dasarOpsional = String(c.parsed.dasar_opsional).trim();
      }
      if (String(c.parsed.pengarahan_umum || '').trim()) {
        pengarahanParts.push(String(c.parsed.pengarahan_umum).trim());
      }
      if (String(c.parsed.kesimpulan || '').trim()) {
        kesimpulanParts.push(String(c.parsed.kesimpulan).trim());
      }
      if (String(c.parsed.transkrip_ringkas || '').trim()) {
        transkripParts.push(String(c.parsed.transkrip_ringkas).trim());
      }
      if (Array.isArray(c.parsed.pembahasan)) {
        for (const row of c.parsed.pembahasan) {
          if (row && typeof row === 'object') mergedPembahasan.push(row);
        }
      }
    }
  } else {
    failedErrors.push(String(c.timeWindowLabel || ('Segmen #' + (Number(c.chunkIndex) + 1))) + ': ' + String(c.errorMsg || 'Gagal'));
  }
}

const chunkSalvagedObj = okCount > 0
  ? {
      dasar_opsional: dasarOpsional,
      pengarahan_umum: (() => {
        const seen = new Set();
        const res = [];
        for (const p of pengarahanParts) {
          for (const s of String(p || '').split(/\r?\n+|(?<=[.!?])\s+/)) {
            const t = String(s || '').trim();
            const n = t.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
            if (t && (!n || !seen.has(n))) { if (n) seen.add(n); res.push(t); }
          }
        }
        return res.join(' ');
      })(),
      kesimpulan: (() => {
        const seen = new Set();
        const res = [];
        for (const p of kesimpulanParts) {
          for (const s of String(p || '').split(/\r?\n+|(?<=[.!?])\s+/)) {
            const t = String(s || '').trim();
            const n = t.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
            if (t && (!n || !seen.has(n))) { if (n) seen.add(n); res.push(t); }
          }
        }
        return res.join(' ');
      })(),
      transkrip_ringkas: transkripParts.join(' '),
      pembahasan: mergedPembahasan,
    }
  : null;

return [
  {
    json: {
      fromChunkPipeline: true,
      chunkCombinedText: textSections.join(NL + NL),
      chunkSalvagedObj,
      chunkSoftError: failedErrors.join(' ; '),
      chunkStats: {
        totalChunks: baseClips.length,
        okCount,
        failedCount: baseClips.length - okCount,
        modelsUsed: baseClips.map((c) => c.modelUsed),
      },
    },
  },
];

